export type IcName = 'play' | 'pause' | 'stop' | 'play-skip-back' | 'play-skip-forward' | 'repeat' | 'shuffle' | 'volume-high' | 'volume-mute' | 'volume-off' | 'musical-note' | 'musical-notes' | 'albums' | 'library' | 'radio' | 'headset' | 'bar-chart' | 'home' | 'search' | 'heart' | 'time' | 'list' | 'document-text' | 'document' | 'folder' | 'folder-open' | 'desktop' | 'grid' | 'browsers' | 'expand' | 'contract' | 'remove' | 'close' | 'add' | 'add-circle' | 'chevron-down' | 'locate' | 'settings' | 'options' | 'extension-puzzle' | 'color-palette' | 'contrast' | 'moon' | 'sunny' | 'aperture' | 'flower' | 'shirt' | 'create' | 'brush'

export function Ic({ name, variant = 'o', size = 14, className, stroke }: { name: IcName; variant?: 'o' | 'f'; size?: number; className?: string; stroke?: boolean }) {
  const key = variant === 'o' ? name + '-o' : name
  const rec = IC[key] || IC[name] || IC[name + '-o']
  if (!rec) return null
  return (
    <svg className={className} viewBox={rec.vb} width={size} height={size}
         fill="currentColor" style={{ display: 'block', flex: '0 0 auto' }}
         aria-hidden="true" dangerouslySetInnerHTML={{ __html: rec.d }} />
  )
}
